const req = $('Preparer requete').first().json;
const moi = Number($('Appel outil').first().json.user_id);
function items(n) { try { const r = $(n).first().json; return (r && r.ok && r.data && r.data.items) || []; } catch (e) { return []; } }
const now = DateTime.now().setZone('Europe/Paris');
const NOMS = { 5066: 'Laurent', 5069: 'Christophe', 9965: 'Axel', 5198: 'Axel' };
const moiIds = moi === 9965 ? [9965, 5198] : [moi];
const LIB = { 1: ' (approx.)', 2: ' (demi-journee)', 3: ' (journee entiere)' };
function test(s) {
  s = String(s || '').toLowerCase();
  if (/devis|visite technique|visite avant|metre|métré|chiffrage/.test(s)) return 'devis';
  if (/install|pose|mise en service/.test(s)) return 'installation';
  if (/d[ée]pannage|panne|fuite|erreur|ne fonctionne|ne fait plus|ne d[ée]marre/.test(s)) return 'depannage';
  if (/entretien|maintenance|nettoyage|r[ée]vision/.test(s)) return 'maintenance';
  return null;
}
function cat(ev) {
  if (ev.category === 'task') return 'tache';
  return test(ev.type) || (ev.maintenance ? 'maintenance' : null) || test(ev.title) || (ev.category === 'meeting' ? 'rdv' : 'intervention');
}
const vus = new Set();
const lignes = [];
const tous = items('Lire interventions').concat(items('Lire RDV'))
  .filter(ev => { if (vus.has(String(ev.id))) return false; vus.add(String(ev.id)); return ev.lifecycleState !== 'cancelled'; })
  .sort((a, b) => String(a.start).localeCompare(String(b.start)));
for (const ev of tous) {
  const c = cat(ev);
  if (req.categorie !== 'tous' && c !== req.categorie) continue;
  const dt = DateTime.fromISO(ev.start, { zone: 'utc' }).setZone('Europe/Paris');
  const jour = dt.setLocale('fr').toFormat('ccc dd/MM');
  const heure = ev.codeHoraire === 4 ? 'date a caler' : dt.toFormat("HH'h'mm") + (LIB[ev.codeHoraire] || '');
  const ids = ev.technicianIds || [];
  const avecMoi = ids.some(t => moiIds.includes(t));
  const autres = [...new Set(ids.filter(t => !moiIds.includes(t)).map(t => NOMS[t] || ('tech ' + t)))];
  const techTxt = avecMoi ? ('toi' + (autres.length ? ' + ' + autres.join('+') : '')) : (autres.join('+') || 'non attribue');
  const statut = ev.finished ? 'termine' : (dt < now ? 'passe' : 'a venir');
  const m = String(ev.address || '').match(/(\d{5})[\s,]+(.+)$/);
  const ville = m ? m[2].trim() : (ev.address || '');
  const objet = [ev.type, ev.title && ev.title !== ev.type ? ev.title : ''].filter(Boolean).join(' : ').replace(/\s+/g, ' ').slice(0, 120);
  lignes.push([jour + ' ' + heure, c, (ev.client && ev.client.name) || '-', ville || '-', objet, 'qui: ' + techTxt, 'statut: ' + statut, 'event_id: ' + ev.id, 'client_id: ' + ((ev.client && ev.client.id) || '-'), ev.secondReference ? 'devis: ' + ev.secondReference : '', ev.sousContrat ? 'sous contrat' : ''].filter(Boolean).join(' | '));
}
const entete = 'Planning du ' + req.date + ' sur ' + req.jours + ' jour(s), categorie ' + req.categorie + ' (qui: toi = la personne qui pose la question) :';
const corps = lignes.length ? lignes.slice(0, 60).join('\n') + (lignes.length > 60 ? '\n(' + (lignes.length - 60) + ' autres non affiches)' : '') : 'Aucun evenement.';
return [{ json: { resultat: entete + '\n' + corps } }];

const i = $input.first().json;
const now = DateTime.now().setZone('Europe/Paris');
let d = DateTime.fromISO(String(i.date_debut || ''), { zone: 'Europe/Paris' });
if (!d.isValid) d = now;
const ecart = d.startOf('day').diff(now.startOf('day'), 'days').days;
if (ecart < -90 || ecart > 120) d = now;
const jours = Math.min(Math.max(parseInt(i.jours || 1, 10) || 1, 1), 31);
const IDS = { laurent: [5066], christophe: [5069], axel: [9965, 5198] };
const t = String(i.technicien || 'tous').toLowerCase().trim();
const role = String(i.role || '');
const libre = role === 'admin' || role === 'manager';
const moi = String(i.user_id) === '9965' ? [9965, 5198] : [Number(i.user_id)];
let techIds = [];
if (!libre) techIds = moi;
else if (t === 'moi') techIds = moi;
else if (IDS[t]) techIds = IDS[t];
return [{ json: { date: d.toISODate(), jours, techIds: techIds.map(String), categorie: String(i.categorie || 'tous').toLowerCase().trim() } }];
